use roman::{to_roman, from_roman};

#[test]
fn test_to_roman_basic() {
    assert_eq!(to_roman(1), "I");
    assert_eq!(to_roman(4), "IV");
    assert_eq!(to_roman(9), "IX");
    assert_eq!(to_roman(14), "XIV");
    assert_eq!(to_roman(1994), "MCMXCIV");
    assert_eq!(to_roman(3999), "MMMCMXCIX");
}

#[test]
fn test_from_roman_basic() {
    assert_eq!(from_roman("I"), 1);
    assert_eq!(from_roman("IV"), 4);
    assert_eq!(from_roman("IX"), 9);
    assert_eq!(from_roman("XIV"), 14);
    assert_eq!(from_roman("MCMXCIV"), 1994);
}

#[test]
fn test_round_trip() {
    for n in [1, 4, 9, 40, 90, 400, 900, 1000, 1994, 3999] {
        assert_eq!(from_roman(&to_roman(n)), n, "round trip failed for {}", n);
    }
}

#[test]
fn test_to_roman_subtractive() {
    assert_eq!(to_roman(40), "XL");
    assert_eq!(to_roman(90), "XC");
    assert_eq!(to_roman(400), "CD");
    assert_eq!(to_roman(900), "CM");
}

#[test]
fn test_from_roman_subtractive() {
    assert_eq!(from_roman("XL"), 40);
    assert_eq!(from_roman("XC"), 90);
    assert_eq!(from_roman("CD"), 400);
    assert_eq!(from_roman("CM"), 900);
}

